# Initially generated by GitHub Copilot.
"""Verifier driver: build dispatch dict, run verifiers, report results."""

import sys
from types import ModuleType
from typing import Callable, Mapping

from author_util.claim import ClaimCollection, ClaimRecord
from verify_mp import payload_examples
from verify_mp import verifiers_plus, verifiers_both, verifiers_plain
from verify_mp.corpus import Context
from verify_mp.verifiers_both import REGISTRY as REGISTRY_BOTH
from verify_mp.verifiers_plain import REGISTRY as REGISTRY_PLAIN
from verify_mp.verifiers_plus import REGISTRY as REGISTRY_PLUS

VerifierFn = Callable[[ClaimRecord, Context], None]

_VERIFIER_MODULES: tuple[ModuleType, ...] = (
    verifiers_plus,
    verifiers_both,
    verifiers_plain,
)


def _module_label(module: ModuleType) -> str:
    return module.__name__.split(".")[-1]


def _registry_for_module(module: ModuleType) -> Mapping[str, VerifierFn]:
    """Return explicit REGISTRY symbol for known modules, else module.REGISTRY."""
    if module is verifiers_plus:
        return REGISTRY_PLUS
    if module is verifiers_both:
        return REGISTRY_BOTH
    if module is verifiers_plain:
        return REGISTRY_PLAIN
    return module.REGISTRY


def _verifier_sources() -> tuple[tuple[str, ModuleType, Mapping[str, VerifierFn]], ...]:
    """Return (module_label, module, registry) tuples for all verifier modules."""
    result: list[tuple[str, ModuleType, Mapping[str, VerifierFn]]] = []
    for module in _VERIFIER_MODULES:
        # Keep explicit symbol links for discoverability in tooling; fall back to
        # module.REGISTRY for test doubles.
        registry = _registry_for_module(module)
        result.append((_module_label(module), module, registry))
    return tuple(result)


def _records_by_id(
    claims: ClaimCollection | Mapping[str, ClaimRecord],
) -> Mapping[str, ClaimRecord]:
    if isinstance(claims, ClaimCollection):
        return claims.records_by_id
    return claims


def merged_registry() -> dict[str, VerifierFn]:
    """Return all verifier REGISTRY entries merged across verifier modules."""
    merged: dict[str, VerifierFn] = {}
    for _module_name, _module, registry in _verifier_sources():
        for claim_id, fn in registry.items():
            assert (
                claim_id not in merged
            ), f"duplicate verifier REGISTRY key across modules: {claim_id!r}"
            merged[claim_id] = fn
    return merged


def build_verifiers(
    claims: ClaimCollection | Mapping[str, ClaimRecord],
) -> dict:
    """Map each claim id to its verifier function (where one exists)."""
    records = _records_by_id(claims)
    registry = merged_registry()
    return {
        claim_id: registry[claim_id] for claim_id in records if claim_id in registry
    }


def _unregistered_verify_functions_by_module() -> dict[str, list[str]]:
    """Return verify_* functions not referenced by module REGISTRY."""
    unregistered_by_module: dict[str, list[str]] = {}
    for module_name, module, registry in _verifier_sources():
        verify_functions = {
            fn
            for name, fn in vars(module).items()
            if name.startswith("verify_") and callable(fn)
        }
        registered_functions = set(registry.values())
        unregistered = sorted(
            fn.__name__ for fn in (verify_functions - registered_functions)
        )
        if unregistered:
            unregistered_by_module[module_name] = unregistered
    return unregistered_by_module


def _exit_if_unregistered_verify_functions() -> None:
    """Print unregistered verifier functions and exit with status 2."""
    unregistered_by_module = _unregistered_verify_functions_by_module()
    if not unregistered_by_module:
        return

    print(
        "ERROR: verifier function(s) not referenced by module REGISTRY:",
        file=sys.stderr,
    )
    for module_name, fn_names in sorted(unregistered_by_module.items()):
        print(f"  {module_name}", file=sys.stderr)
        for fn_name in fn_names:
            print(f"    {fn_name}", file=sys.stderr)
    sys.exit(2)


def _exit_if_stale_registry_keys(
    registry: Mapping[str, VerifierFn],
    records: Mapping[str, ClaimRecord],
) -> None:
    """Print stale REGISTRY keys and exit with status 2."""
    stale_registry_keys = sorted(set(registry) - set(records))
    if not stale_registry_keys:
        return

    print("ERROR: REGISTRY key(s) with no matching claim id:", file=sys.stderr)
    for claim_id in stale_registry_keys:
        print(f"  {claim_id}", file=sys.stderr)
    sys.exit(2)


def _print_results(
    passed: list[str],
    failed: list[tuple[str, str]],
    pending: list[str],
) -> None:
    """Print verifier results and summary counts."""
    print("Results:")
    for claim_id in passed:
        print(f"  PASS    {claim_id}")
    for claim_id, msg in failed:
        print(f"  FAIL    {claim_id}")
        print(f"          {msg}")
    for claim_id in pending:
        print(f"  pending {claim_id}")

    print(f"\n{len(passed)} passed, {len(failed)} failed, {len(pending)} pending")


def run(
    ctx: Context,
    claims: ClaimCollection | Mapping[str, ClaimRecord],
) -> None:
    """Run all verifiers; print a report; exit with code 1 if any verifier fails.

    Claims with no verifier are reported as 'pending' (not failures), since this
    verifier suite is built incrementally. Explicit-REGISTRY mismatches are
    treated as errors: stale REGISTRY keys and unregistered verify_* functions.
    """
    records = _records_by_id(claims)
    ctx.claim_records = records
    registry = merged_registry()
    verifiers = {
        claim_id: registry[claim_id] for claim_id in records if claim_id in registry
    }

    _exit_if_stale_registry_keys(registry, records)
    _exit_if_unregistered_verify_functions()

    passed: list[str] = []
    failed: list[tuple[str, str]] = []
    pending: list[str] = []

    for claim_id, record in sorted(records.items()):
        has_generic_example_verifier = payload_examples.is_example_claim(record)

        if claim_id not in verifiers and not has_generic_example_verifier:
            pending.append(claim_id)
            continue

        fn = verifiers.get(claim_id)
        try:
            if has_generic_example_verifier:
                payload_examples.verify_example_payload(record, ctx)
            if fn is not None:
                fn(record, ctx)
            passed.append(claim_id)
        except AssertionError as exc:
            failed.append((claim_id, str(exc)))

    _print_results(passed, failed, pending)
    if failed:
        sys.exit(1)
